# Contract Bytecode (from Remix - replace with your actual bytecode)
CONTRACT_BYTECODE =""

def connect_to_ganache():
    """Connect to Ganache and verify connection"""
    try:
        w3 = Web3(Web3.HTTPProvider(RPC_URL))
        
        if not w3.is_connected():
            print(" Failed to connect to Ganache")
            print(f"   Make sure Ganache is running on {RPC_URL}")
            return None
        
        print(" Connected to Ganache")
        print(f"   Chain ID: {w3.eth.chain_id}")
        print(f"   Latest Block: {w3.eth.block_number}")
        return w3
    
    except Exception as e:
        print(f" Connection error: {e}")
        return None

def validate_account(w3, address, private_key):
    """Validate that the account exists and has balance"""
    try:
        # Check balance
        balance = w3.eth.get_balance(address)
        balance_eth = w3.from_wei(balance, 'ether')
        
        if balance_eth == 0:
            print(f"Warning: Account has 0 ETH balance")
            return False
        
        print(f"Account verified: {address}")
        print(f"Balance: {balance_eth} ETH")
        return True
    
    except Exception as e:
        print(f"Account validation error: {e}")
        return False

def deploy_contract(w3):
    """Deploy the TodoList contract to Ganache"""
    try:
        print("\n" + "="*60)
        print("DEPLOYING CONTRACT")
        print("="*60)
        
        # Validate account
        if not validate_account(w3, FROM_ADDRESS, PRIVATE_KEY):
            return None
        
        # Check nonce
        nonce = w3.eth.get_transaction_count(FROM_ADDRESS)
        print(f"\n Deployment details:")
        print(f"   From: {FROM_ADDRESS}")
        print(f"   Nonce: {nonce}")
        print(f"   Gas Price: {w3.from_wei(w3.eth.gas_price, 'gwei')} Gwei")
        
        # Build deployment transaction
        transaction = {
            'from': FROM_ADDRESS,
            'nonce': nonce,
            'gas': 3000000,
            'gasPrice': w3.eth.gas_price,
            'data': '0x' + CONTRACT_BYTECODE,
            'chainId': w3.eth.chain_id
        }
        
        # Sign transaction
        signed_txn = w3.eth.account.sign_transaction(transaction, PRIVATE_KEY)
        
        # Send transaction
        tx_hash = w3.eth.send_raw_transaction(signed_txn.raw_transaction)
        print(f" Transaction sent: {tx_hash.hex()}")
        
        # Wait for receipt
        print("⏳ Waiting for transaction confirmation...")
        tx_receipt = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=30)
        
        contract_address = tx_receipt['contractAddress']
        gas_used = tx_receipt['gasUsed']
        
        print(f"\nContract deployed successfully!")
        print(f"   Address: {contract_address}")
        print(f"   Block: {tx_receipt['blockNumber']}")
        print(f"   Gas Used: {gas_used}")
        
        # Save contract address to file
        save_contract_address(contract_address)
        
        return contract_address
    
    except Exception as e:
        print(f"\n Deployment error: {e}")
        return None

def save_contract_address(address):
    """Save contract address to file for later use"""
    try:
        with open('contract_address.txt', 'w') as f:
            f.write(address)
        print(f"   Address saved to: contract_address.txt")
    except Exception as e:
        print(f"   Could not save address: {e}")

